import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百五十四章 没有永远存在的事物","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/254第二百五十四章 没有永远存在的事物.md","filePath":"meditation/巴利文大藏经/254第二百五十四章 没有永远存在的事物.md"}'),r={name:"meditation/巴利文大藏经/254第二百五十四章 没有永远存在的事物.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百五十四章-没有永远存在的事物",tabindex:"-1"},[l("第二百五十四章 没有永远存在的事物 "),e("a",{class:"header-anchor",href:"#第二百五十四章-没有永远存在的事物","aria-label":'Permalink to "第二百五十四章 没有永远存在的事物"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应45经/无常经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！物质事物、物质身体、感受、念想、行为、认识、分别、判断是随时在变化的，是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的。物质事物是会衰败、灭亡、消失的，物质身体是会生病、衰老、死亡的。感受、念想、行为、认识、分别、判断是会消退、灭尽、消失的，既然如此，那么物质事物、物质身体、感受、念想、行为、认识、分别、判断最终带来的都是痛苦；物质事物、物质身体、感受、念想、行为、认识、分别、判断无法永远的存在，无法永恒的保持不变，无法永远的拥有，那么就没有真实不变的我存在，就没有青春永驻、永远不死的我存在，就没有可以永远拥有、永远存在、永远保持不变的物质事物、物质身体、感受、念想、行为、认识、分别、判断的存在。",-1),e("p",null,"比丘们！应该用正确的智慧，这样来看待物质事物、物质身体、感受、念想、行为、认识、分别、判断：「物质事物、物质身体、感受、念想、行为、认识、分别、判断不是我所拥有的，我不是这个物质事物、物质身体、感受、念想、行为、认识、分别、判断，这个物质事物、物质身体、感受、念想、行为、认识、分别、判断不是真实不变、永远存在的我。」简单的说就是：「这不是我的，我不是这个，这不是真实不变、永远存在的我。」当经常这样观想的时候，那么内心就不会被物质事物、物质身体、感受、念想、行为、认识、分别、判断扰动、污染、影响而生起喜怒哀乐等等无数的念想，内心就能长久的保持清净安宁，就不会再去执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，这样就不会再次产生忧愁、悲伤、苦闷、忧虑、绝望等等无数的烦恼和痛苦，就能最终从一切的烦恼和痛苦中解脱出来。",-1),e("p",null,"比丘们！如果修行人的内心不被色界、感受界、念想界、行为界、识界（色界解释，见第一百零三章；感受界、念想界、行为界解释，见第二百一十九章；识界就是眼识、耳识、鼻识、舌识、身识、意识，眼识、耳识、鼻识、舌识、身识、意识解释，见第一百八十八章）扰动、污染、影响而生起喜怒哀乐等等无数的念想，他们的内心就能长久的保持清净安宁，就不会再去执着和挂念色界、感受界、念想界、行为界、识界，这样他们就不会再次产生忧愁、悲伤、苦闷、忧虑、绝望等等无数的烦恼和痛苦，就能最终从一切的烦恼和痛苦中解脱出来。”",-1),e("p",null,"解脱后就能保持内心长久的清净安宁，内心清净安宁后就不会被世间一切的事物扰动、困惑、影响，就不会执着和挂念任何的念想，就不会生起任何的念想，没有执着，没有挂念，没有念想，就进入没有烦恼和痛苦的涅槃境界，就能彻底明白：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生的世间了，已经彻底从生死轮回中解脱出来。」",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
